n = int(input())

x = 1
ans = None

while x**3 <= n:
    s = str(x**3)
    l = len(s)
    kai = True
    for i in range(l // 2):
        if s[i] != s[l - i - 1]:
            kai = False
            break
    if kai:
        ans = s
    x += 1

if ans is not None:
    print(ans)
